412	const hasSingleInstanceLock = app.requestSingleInstanceLock();
413	if (!hasSingleInstanceLock) {
414	  app.quit();
415	} else {
416	  app.on("second-instance", (_event, argv) => {
417	    handleDeepLinkArguments(argv);
418	    if (mainWindow) {
419	      if (mainWindow.isMinimized()) mainWindow.restore();
420	      mainWindow.focus();
421	    }
422	  });
423	  app.on("open-url", (event, url) => {
424	    event.preventDefault();
425	    enqueueDeepLink(url);
426	  });
427	
428	  void app.whenReady().then(async () => {
429	    if (app.isPackaged) app.setAsDefaultProtocolClient("inkling");
430	    else {
431	      app.setAsDefaultProtocolClient("inkling", process.execPath, [
432	        resolve(process.argv[1] ?? "."),
433	      ]);
434	    }
435	    registerLibraryCommands();
436	    try {
437	      captureServer = await startCaptureServer({
438	        libraryDirectory,
439	        captureUrl: (input) => {
440	          if (!libraryStorage) initializeLibraryStorage();
441	          return requireLibraryStorage().captureUrl(input);
442	        },
443	      });
444	    } catch (error) {
445	      console.error(
446	        `capture server unavailable: ${error instanceof Error ? error.message : String(error)}`,
447	      );
448	    }
449	    await protocol.handle("app", serveAppAsset);
450	    allowCanvasReadableImages();
451	    handleDeepLinkArguments(process.argv);
452	    createWindow();
453	
454	    app.on("activate", () => {
455	      if (BrowserWindow.getAllWindows().length === 0) createWindow();
456	    });
457	    app.on("window-all-closed", () => {
458	      if (process.platform !== "darwin") app.quit();
459	    });
460	    let quitDrainStarted = false;
461	    let quitDrainComplete = false;
462	    app.on("before-quit", (event) => {
463	      if (quitDrainComplete) return;
464	      event.preventDefault();
465	      if (quitDrainStarted) return;
466	      quitDrainStarted = true;
467	      jobWorker?.stop();
468	      thumbnailWorker?.stop();
469	      void (async () => {
470	        try {
471	          await captureServer?.close();
472	        } catch (error) {
473	          console.error(
474	            `capture server shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
475	          );
476	        }
477	        try {
478	          await aiJobProcessors?.close();
479	        } catch (error) {
480	          console.error(
481	            `background jobs shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
482	          );
483	        }
484	        try {
485	          libraryStorage?.db.close();
486	        } catch (error) {
487	          console.error(
488	            `library shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
489	          );
490	        }
491	        quitDrainComplete = true;
492	        app.quit();
493	      })();
494	    });
495	  });
496	}
