381	export async function assetUrl(path: string | null) {
382	  if (!path) return undefined;
383	  if (isElectronRuntime()) {
384	    const relativePath = path.replace(/\\/g, "/");
385	    if (!relativePath.startsWith("assets/")) return undefined;
386	    const segments = relativePath.slice("assets/".length).split("/");
387	    if (
388	      segments.some(
389	        (segment) => !segment || segment === "." || segment === ".." || segment.includes(":"),
390	      )
391	    ) {
392	      return undefined;
393	    }
394	    const encodedPath = segments.map(encodeURIComponent).join("/");
395	    return `app://local/library-assets/${encodedPath}`;
396	  }
397	  return path;
398	}
