      const host = videoLink.provider === "youtube" ? "www.youtube.com" : "vimeo.com";
      const response = await fetchImpl(
        `https://${host}/oembed.json?url=${encodeURIComponent(videoLink.sourceUrl)}`,
        {
          headers: { Accept: "application/json", "User-Agent": userAgent },
          redirect: "follow",
          signal: controller.signal,
        },
      );
      if (response.ok) {
        const body = await readResponseText(
          response,
          Math.min(maxResponseBytes, 512 * 1024),
          sourceUrl,
        );
        const metadata = JSON.parse(body) as {
          title?: unknown;
          author_name?: unknown;
          thumbnail_url?: unknown;
        };
        if (typeof metadata.title === "string" && metadata.title.trim())
          title = metadata.title.trim();
        if (typeof metadata.author_name === "string" && metadata.author_name.trim())
          author = metadata.author_name.trim();
        if (typeof metadata.thumbnail_url === "string") {
          poster = normalizeHttpUrl(metadata.thumbnail_url, sourceUrl) ?? poster;
        }
      }
    } catch {
      // oEmbed is enrichment only. The validated URL remains indexable when
      // a provider blocks or rate-limits metadata requests.
    } finally {
      clearTimeout(timeout);
    }
  }

  return {
    sourceUrl,
    fetchedUrl: sourceUrl,
    canonicalUrl: sourceUrl,
    title,
    description: author
      ? `${providerLabel(videoLink.provider)} · ${author}`
      : `${providerLabel(videoLink.provider)} video`,
    author,
    publishedDate: null,
    html: "",
    text: title,
    imageUrls: poster ? [poster] : [],
    imageDimensions: [],
    safeEmbeds: [
      {
        kind: "iframe",
        provider: videoLink.provider,
        sourceUrl: videoLink.sourceUrl,
        embedUrl: videoLink.embedUrl,
        title,
      },
    ],
    extractor: "fallback",
  };
}

export async function ingestUrl(
  input: string,
  options: UrlIngestionOptions = {},
): Promise<NormalizedArticle> {
  const sourceUrl = parseHttpUrl(input, {
    allowPrivateNetwork: options.allowPrivateNetwork,
  }).toString();
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const maxResponseBytes = options.maxResponseBytes ?? DEFAULT_MAX_RESPONSE_BYTES;
  const fetchImpl = options.fetch ?? globalThis.fetch;

  const videoLink = videoLinkFromSourceUrl(sourceUrl);
  if (videoLink) {
    return ingestVideoLink(
      sourceUrl,
      videoLink,
      fetchImpl,
      timeoutMs,
      maxResponseBytes,
      options.userAgent ?? DEFAULT_USER_AGENT,
    );
  }

  if (!fetchImpl) {
    throw new UrlIngestionError("network-error", "No fetch implementation is available.", {
      url: sourceUrl,
    });
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  let response: Response;
  let fetchedUrl = sourceUrl;

  let xPost: XPostMetadata | null = null;
  if (parseXPostUrl(sourceUrl)) {
    try {
      const oEmbedResponse = await fetchImpl(xPostOEmbedUrl(sourceUrl), {
        headers: {
          Accept: "application/json",
          "User-Agent": options.userAgent ?? DEFAULT_USER_AGENT,
        },
        redirect: "follow",
        signal: controller.signal,
      });

      if (oEmbedResponse.ok) {
        const oEmbedBody = await readResponseText(
          oEmbedResponse,
          Math.min(maxResponseBytes, 512 * 1024),
          sourceUrl,
        );
        try {
          xPost = normalizeXPostOEmbed(
            sourceUrl,
            JSON.parse(oEmbedBody) as Record<string, unknown>,
          );
        } catch {
          xPost = null;
        }
      }
    } catch {
      // X can block or rate-limit the oEmbed request. Fall through to the
      // normal page pipeline so capture still has a chance to succeed.
    }
  }

  if (xPost) {
    clearTimeout(timeout);
    const text = xPost.text || `${xPost.authorName ?? "X"} post`;
    return {
      sourceUrl,
      fetchedUrl: sourceUrl,
      canonicalUrl: xPost.postUrl,
      title: xPost.authorName ? `${xPost.authorName}'s post` : "X post",
      description: text,
      author: xPost.authorName ?? "",
      publishedDate: xPost.publishedDate ?? null,
      html: xPost.embedHtml ?? "",
      text,
      imageUrls: [],
      imageDimensions: [],
      safeEmbeds: [],
      extractor: "fallback",
      social: xPost,
    };
  }

  try {
    for (let redirectCount = 0; ; redirectCount++) {
      // codeql[js/request-forgery,javascript/ssrf]: This local-first desktop pipeline intentionally fetches user-selected public URLs. parseHttpUrl rejects non-HTTP(S), credentialed, and private-network destinations before this boundary, and redirect targets are validated before the next request.
      response = await fetchImpl(fetchedUrl, {
        headers: {
          Accept: "text/html,application/xhtml+xml;q=0.9,text/plain;q=0.5",
          "User-Agent": options.userAgent ?? DEFAULT_USER_AGENT,
        },
        redirect: "manual",
        signal: controller.signal,
      });

      if (!isRedirectStatus(response.status)) break;
      if (redirectCount >= MAX_REDIRECTS) {
        throw new UrlIngestionError("redirect-error", "The page redirected too many times.", {
          url: fetchedUrl,
        });
      }

      const location = response.headers.get("location");
      const redirectUrl = location ? normalizeHttpUrl(location, fetchedUrl) : null;
      if (!redirectUrl) {
        throw new UrlIngestionError(
          "redirect-error",
          "The page returned an invalid redirect destination.",
          {
            url: fetchedUrl,
          },
        );
      }

      fetchedUrl = parseHttpUrl(redirectUrl, {
        allowPrivateNetwork: options.allowPrivateNetwork,
      }).toString();
    }
  } catch (cause) {
    clearTimeout(timeout);
    if (cause instanceof UrlIngestionError) throw cause;
    if (controller.signal.aborted) {
      throw new UrlIngestionError("timeout", "The page took too long to download.", {
        cause,
        url: sourceUrl,
      });
    }
    throw new UrlIngestionError("network-error", "The page could not be downloaded.", {
      cause,
      url: sourceUrl,
    });
  }

  let rawHtml: string;
  try {
    if (!response.ok) {
      throw new UrlIngestionError("http-error", `The page returned HTTP ${response.status}.`, {
        status: response.status,
        url: sourceUrl,
      });
    }

    const contentType = response.headers.get("content-type")?.toLowerCase() ?? "";
    if (
      contentType &&
      !contentType.includes("text/html") &&
      !contentType.includes("application/xhtml+xml") &&
      !contentType.startsWith("text/plain")
    ) {
      throw new UrlIngestionError(
        "unsupported-content-type",
        "The URL did not return an HTML document.",
        {
          url: fetchedUrl,
        },
      );
    }

    rawHtml = await readResponseText(response, maxResponseBytes, fetchedUrl);
  } catch (error) {
    if (error instanceof UrlIngestionError) throw error;
    if (controller.signal.aborted) {
      throw new UrlIngestionError("timeout", "The page took too long to download.", {
        cause: error,
        url: fetchedUrl,
      });
    }
    throw new UrlIngestionError("network-error", "The page could not be read.", {
      cause: error,
      url: fetchedUrl,
    });
  } finally {
    clearTimeout(timeout);
  }

  const sourceDocument = parseDocument(rawHtml);
  const extractionDocument = parseDocument(rawHtml);
  promoteInfoAsides(extractionDocument);
  const fallback = extractFallback(sourceDocument, fetchedUrl);
  const adapter = options.defuddleAdapter ?? new DefaultDefuddleAdapter();
  let extraction = fallback;
  let extractor: "defuddle" | "fallback" = "fallback";

  try {
    const defuddleExtraction = await adapter.extract(extractionDocument, fetchedUrl);
    extraction = mergeExtraction(defuddleExtraction, fallback);
    if (hasReadableText(defuddleExtraction.contentHtml)) extractor = "defuddle";
  } catch {
    extraction = fallback;
  }

  const byline = visibleByline(sourceDocument);
  if (byline.author) extraction = { ...extraction, author: byline.author };
  if (byline.publishedDate) extraction = { ...extraction, publishedDate: byline.publishedDate };

  const title = normalizeText(extraction.title) || new URL(fetchedUrl).hostname;
  const description = normalizeText(extraction.description);
  const contentDocument = parseDocument(
    `<html><head></head><body>${sanitizeHtml(extraction.contentHtml ?? "", fetchedUrl)}</body></html>`,
  );
  const html = cleanArticleHeadings(contentDocument, title, description);
  if (!hasReadableText(html)) {
    throw new UrlIngestionError(
      "extraction-failed",
      "No readable article content was found on the page.",
      {
        url: fetchedUrl,
      },
    );
  }

  const canonicalUrl = normalizeHttpUrl(extraction.canonicalUrl, fetchedUrl) ?? fetchedUrl;
  const imageUrls = uniqueStrings([
    ...collectImageUrls(sourceDocument, fetchedUrl),
    ...(extraction.imageUrls ?? [])
      .map((value) => normalizeHttpUrl(value, fetchedUrl))
      .filter((value): value is string => value !== null),
  ]);
  const imageDimensions = (extraction.imageDimensions ?? [])
    .map((value) => {
      const url = normalizeHttpUrl(value.url, fetchedUrl);
      return url ? { ...value, url } : null;
    })
    .filter(
      (value, index, values): value is NonNullable<typeof value> =>
        value !== null &&
        imageUrls.includes(value.url) &&
        values.findIndex((candidate) => candidate?.url === value.url) === index,
    );

  return {
    sourceUrl,
    fetchedUrl,
    canonicalUrl,
    title,
    description,
    author: normalizeText(extraction.author),
    publishedDate: normalizePublishedDate(extraction.publishedDate),
    html,
    text: htmlToText(html),
    imageUrls,
    imageDimensions,
    safeEmbeds: collectSafeEmbeds(sourceDocument, fetchedUrl),
    extractor,
  };
}

