  url: string;
  width: number;
  height: number;
}

export interface XPostMetadata {
  provider: "x";
  postUrl: string;
  postId: string;
  embedHtml?: string;
  authorName?: string;
  authorUrl?: string;
  authorHandle?: string;
  text?: string;
