export interface NormalizedArticle {
  sourceUrl: string;
  fetchedUrl: string;
  canonicalUrl: string;
  title: string;
  description: string;
  author: string;
  publishedDate: string | null;
  html: string;
  text: string;
  imageUrls: string[];
