console.log(d instanceof Error, d.message);
const t = await Effect.runPromise(Effect.never.pipe(Effect.timeout("10 millis"))).catch((x) => x);
console.log(t._tag, t.message);
EOF
bun .probe.ts; rm .probe.ts

