        this.db.exec("BEGIN IMMEDIATE");
        const currentItemIds = new Set(
          this.db
            .prepare("SELECT id FROM items")
            .all()
            .map((row) => row.id),
        );
        const currentSpaceIds = new Set(
          this.db
            .prepare("SELECT id FROM spaces")
            .all()
            .map((row) => row.id),
        );
