          this.db
            .prepare(`INSERT INTO items (id, kind, title, description, body, body_format, source_url,
            source_label, local_asset_path, thumbnail_path, ocr_text, metadata, created_at, updated_at, archived, favorite)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
            .run(
              item.id,
              item.kind,
              item.title,
              item.description,
              item.body ?? "",
              item.body_format ?? "md",
              item.source_url,
              item.source_label,
              item.local_asset_path,
              item.thumbnail_path,
              item.ocr_text,
              item.metadata,
              item.created_at,
              item.updated_at,
              item.archived,
              item.favorite,
