export function summariesFromJobs(itemIds: string[], jobs: ProcessingJob[]) {
  const grouped = new Map<string, ProcessingJob[]>();
  for (const job of jobs) {
    const group = grouped.get(job.itemId) ?? [];
    group.push(job);
    grouped.set(job.itemId, group);
