517	test("job leases are owner-bound, renew for five minutes, and recover only after expiry", () => {
518	  const { library } = temporaryLibrary();
519	  const events: string[] = [];
520	  library.db
521	    .prepare(
522	      `INSERT INTO items (id, kind, created_at, updated_at) VALUES ('job-item', 'image', 1, 1)`,
523	    )
524	    .run();
525	  let now = 10_000;
526	  let clockCalls = 0;
527	  const queue = new JobQueue(library.db, {
528	    now: () => {
529	      clockCalls += 1;
530	      return now;
531	    },
532	    onUpdated: (itemId) => events.push(itemId),
533	  });
534	  const jobId = queue.enqueue("job-item", "ocr_image");
535	  expect(queue.enqueue("job-item", "ocr_image")).toBe(jobId);
536	  const claimed = queue.claimNext("worker-a");
537	  expect(claimed?.status).toBe("processing");
538	  expect(claimed?.startedAt).toBe(now);
539	  expect(queue.complete(jobId, "worker-b")).toBe(false);
540	  expect(queue.renew(jobId, "worker-a")).toBe(true);
541	  expect(
542	    library.db.prepare("SELECT lease_until FROM jobs WHERE id = ?").get(jobId).lease_until,
543	  ).toBe(now + JOB_LEASE_MILLIS);
544	  now += JOB_LEASE_MILLIS - 1;
545	  clockCalls = 0;
546	  expect(queue.recoverExpired()).toBe(0);
547	  expect(clockCalls).toBe(1);
548	  now += 2;
549	  clockCalls = 0;
550	  expect(queue.recoverExpired()).toBe(1);
551	  expect(clockCalls).toBe(1);
552	  expect(queue.getForItem("job-item")[0]?.status).toBe("pending");
553	  expect(queue.claimNext("worker-b")?.status).toBe("processing");
554	  expect(queue.fail(jobId, "worker-b", "temporary")).toBe(true);
555	  expect(queue.getForItem("job-item")[0]).toMatchObject({
556	    status: "pending",
557	    retryCount: 1,
558	    errorMessage: "temporary",
559	  });
560	  expect(queue.countActive()).toBe(1);
561	  expect(queue.claimNext("worker-c")?.status).toBe("processing");
562	  expect(queue.complete(jobId, "worker-c")).toBe(true);
563	  expect(queue.getForItem("job-item")[0]).toMatchObject({
564	    status: "completed",
565	    errorMessage: null,
566	  });
567	  expect(events).toEqual([
568	    "job-item",
569	    "job-item",
570	    "job-item",
571	    "job-item",
572	    "job-item",
573	    "job-item",
574	    "job-item",
575	    "job-item",
576	  ]);
577	});
