import { Schema } from "effect";
import type { CommandName } from "./commands.ts";

export { type CommandName, commandChannel, commandNames } from "./commands.ts";

type StoredItemKind = "note" | "article" | "image" | "pdf" | "video" | "file" | "embed";

export type StoredLibraryItem = {
  id: string;
  kind: StoredItemKind | string;
  title: string | null;
  description: string | null;
  body?: string | null;
  bodyFormat?: string | null;
  sourceUrl: string | null;
  sourceLabel: string | null;
  localAssetPath: string | null;
  thumbnailPath: string | null;
  palette?: string[];
  ocrText: string;
  metadata: Record<string, unknown>;
  createdAt: number;
  updatedAt: number;
  archived: boolean;
};

export type StoredLibraryItemDetail = Omit<StoredLibraryItem, "body" | "bodyFormat"> & {
  body: string;
  bodyFormat: string;
};

export type StoredLibraryCard = Omit<
  StoredLibraryItem,
  "body" | "bodyFormat" | "metadata" | "ocrText" | "updatedAt"
> & {
  ocrText: string;
  metadata: {
    tags?: unknown;
    social?: unknown;
    imageUrls?: unknown;
    imageDimensions?: unknown;
    mediaWidth?: unknown;
    mediaHeight?: unknown;
    mediaAspectRatio?: unknown;
    pdfPageCount?: unknown;
    durationSeconds?: unknown;
    fileSizeBytes?: unknown;
    readingMinutes?: unknown;
  };
  hasArticleContent: boolean;
};

export type StoredItemContent = { id: string; body: string; bodyFormat: string };

export type AvailableUpdate = { version: string };

export type ProcessingJobKind = "ocr_image" | "ocr_pdf_page" | "generate_embedding" | "enrich_url";
export type ProcessingJobStatus = "pending" | "processing" | "completed" | "failed";

export type ProcessingJob = {
  id: string;
  itemId: string;
  kind: ProcessingJobKind;
  status: ProcessingJobStatus;
  retryCount: number;
  maxRetries: number;
  errorMessage: string | null;
  createdAt: number;
  startedAt: number | null;
  completedAt: number | null;
  progressCurrent: number;
  progressTotal: number | null;
  progressMessage: string | null;
};

export type SmartSpaceQuery = { text?: string | null; kind?: string | null; tag?: string | null };

/** A "smart" Space re-runs its saved query; a "regular" Space holds the items
 *  the user filed into it. Fixed at creation. */
export type SpaceKind = "smart" | "regular";
export type SpaceColor = "blue" | "orange" | "green" | "pink" | "purple" | "yellow";

export type StoredSpace = {
  id: string;
  name: string;
  color: SpaceColor;
  query: SmartSpaceQuery;
  kind: SpaceKind;
  position: number;
  createdAt: number;
  updatedAt: number;
  /** How many items the Space holds, when the core reports it. The sidebar shows it when present. */
  itemCount?: number;
};

export type StorageStatus = { databasePath: string; fts5Enabled: boolean; schemaVersion: number };
export type LibrarySize = { bytes: number };
export type LastExport = { exportedAt: number; items: number };

export type LibraryExportReport = {
  directory: string;
  items: number;
  archivedItems: number;
  spaces: number;
  assetFiles: number;
  skippedAssets: number;
  databaseBytes: number;
  assetsBytes: number;
};

export type LibraryImportReport = {
  importedItems: number;
  skippedDuplicateItems: number;
  importedSpaces: number;
  skippedDuplicateSpaces: number;
  assetFiles: number;
  unverifiedAssetFiles: number;
};

export type CaptureStatus = { running: boolean; port: number | null; healthUrl: string | null };

// Argument schemas check shape only. Storage keeps the semantic checks (empty
// text, URL schemes, byte limits) so its messages stay the ones users see.
const Text = Schema.String;
const OptionalText = Schema.optional(Schema.String);
const NullableText = Schema.optional(Schema.NullOr(Schema.String));
const Limit = Schema.optional(Schema.Number);
const Metadata = Schema.Record(Schema.String, Schema.Unknown);
const SpaceQuery = Schema.Struct({ text: NullableText, kind: NullableText, tag: NullableText });
const SpaceColorSchema = Schema.Literals(["blue", "orange", "green", "pink", "purple", "yellow"]);
const SpaceKindSchema = Schema.Literals(["smart", "regular"]);
const None = Schema.Struct({});
const ById = Schema.Struct({ id: Text });
const ByItemId = Schema.Struct({ itemId: Text });
const SimilarTo = Schema.Struct({ itemId: Text, limit: Limit });
const SpaceMembership = Schema.Struct({ spaceId: Text, itemId: Text });

export const CreateNoteInput = Schema.Struct({
  title: OptionalText,
  body: Text,
  metadata: Schema.optional(Metadata),
});

export const CreateQuoteInput = Schema.Struct({
  body: Text,
  attribution: OptionalText,
  sourceUrl: OptionalText,
  metadata: Schema.optional(Metadata),
});

export const CaptureUrlInput = Schema.Struct({
  sourceUrl: Text,
  captureSource: OptionalText,
  title: OptionalText,
});

export const SaveFileInput = Schema.Struct({
  fileName: Text,
  mimeType: NullableText,
  kind: NullableText,
  // Structured clone moves a typed array as one block across IPC; storage
  // refuses anything else, such as a number array, with its own message.
  bytes: Schema.Unknown,
});

export const UpdateItemInput = Schema.Struct({
  id: Text,
  title: OptionalText,
  description: OptionalText,
  body: OptionalText,
  bodyFormat: OptionalText,
  sourceUrl: OptionalText,
  sourceLabel: OptionalText,
  localAssetPath: OptionalText,
  thumbnailPath: OptionalText,
  metadata: Schema.optional(Metadata),
  metadataPatch: Schema.optional(Metadata),
  addTag: OptionalText,
});

export const CreateSpaceInput = Schema.Struct({
  name: Text,
  color: Schema.optional(SpaceColorSchema),
  query: Schema.optional(SpaceQuery),
  kind: Schema.optional(SpaceKindSchema),
});

export const UpdateSpaceInput = Schema.Struct({
  id: Text,
  name: OptionalText,
  color: Schema.optional(SpaceColorSchema),
  query: Schema.optional(SpaceQuery),
  position: Schema.optional(Schema.Number),
});

export type CreateNoteInput = typeof CreateNoteInput.Type;
export type CreateQuoteInput = typeof CreateQuoteInput.Type;
export type CaptureUrlInput = typeof CaptureUrlInput.Type;
export type SaveFileInput = typeof SaveFileInput.Type;
export type UpdateItemInput = typeof UpdateItemInput.Type;
export type CreateSpaceInput = typeof CreateSpaceInput.Type;
export type UpdateSpaceInput = typeof UpdateSpaceInput.Type;

export const commandArgs = {
  check_for_updates: None,
  install_update: Schema.Struct({ expectedVersion: Text }),
  initialize_storage: None,
  get_app_version: None,
  get_library_size: Schema.Struct({ refresh: Schema.optional(Schema.Boolean) }),
  get_last_export: None,
  show_library_folder: None,
  show_item_in_folder: ById,
  list_active_items: None,
  list_archived_items: None,
  get_item: ById,
  get_item_cards: Schema.Struct({ ids: Schema.Array(Text) }),
  get_change_count: None,
  get_item_content: ById,
  search_items: Schema.Struct({ query: Text, limit: Limit }),
  search_similar_images: SimilarTo,
  search_similar_text: SimilarTo,
  list_spaces: None,
  create_space: Schema.Struct({ input: CreateSpaceInput }),
  delete_space: ById,
  update_space: Schema.Struct({ input: UpdateSpaceInput }),
  swap_space_positions: Schema.Struct({ firstId: Text, secondId: Text }),
  list_space_items: Schema.Struct({ id: Text, limit: Limit }),
  add_space_item: SpaceMembership,
  remove_space_item: SpaceMembership,
  list_item_spaces: ByItemId,
  create_note: Schema.Struct({ input: CreateNoteInput }),
  create_quote: Schema.Struct({ input: CreateQuoteInput }),
  capture_url: Schema.Struct({ input: CaptureUrlInput }),
  save_file: Schema.Struct({ input: SaveFileInput }),
  resolve_asset_path: Schema.Struct({ path: Text }),
  update_item: Schema.Struct({ input: UpdateItemInput }),
  archive_item: Schema.Struct({ id: Text, archived: Schema.optional(Schema.Boolean) }),
  delete_item: ById,
  export_library: Schema.Struct({
    destination: Text,
    timezoneOffsetMinutes: Schema.optional(Schema.Number),
  }),
  import_library: Schema.Struct({ exportDirectory: Text }),
  get_jobs_for_items: Schema.Struct({ itemIds: Schema.Array(Text) }),
  count_active_jobs: None,
  get_onboarding_state: None,
  complete_onboarding: None,
  enqueue_ocr_job: ByItemId,
  retry_processing_job: Schema.Struct({ jobId: Text }),
  get_capture_status: None,
  get_pairing_token: None,
  regenerate_pairing_token: None,
  select_library_directory: Schema.Struct({ title: Text }),
  "plugin:deep-link|get_current": None,
} satisfies Record<CommandName, Schema.Top>;

export type CommandArgs<C extends CommandName> = (typeof commandArgs)[C]["Type"];

export type CommandResults = {
  check_for_updates: AvailableUpdate | null;
  install_update: AvailableUpdate | null;
  initialize_storage: StorageStatus;
  get_app_version: string;
  get_library_size: LibrarySize;
  get_last_export: LastExport | null;
  show_library_folder: boolean;
  show_item_in_folder: boolean;
  list_active_items: StoredLibraryCard[];
  list_archived_items: StoredLibraryCard[];
  get_item: StoredLibraryItemDetail | null;
  get_item_cards: StoredLibraryCard[];
  get_change_count: number;
  get_item_content: StoredItemContent;
  search_items: StoredLibraryCard[];
  search_similar_images: StoredLibraryCard[];
  search_similar_text: StoredLibraryCard[];
  list_spaces: StoredSpace[];
  create_space: StoredSpace | null;
  delete_space: void;
  update_space: StoredSpace | null;
  swap_space_positions: StoredSpace[];
  list_space_items: StoredLibraryCard[];
  add_space_item: void;
  remove_space_item: void;
  list_item_spaces: string[];
  create_note: StoredLibraryItemDetail | null;
  create_quote: StoredLibraryItemDetail | null;
  capture_url: StoredLibraryItemDetail | null;
  save_file: StoredLibraryItemDetail | null;
  resolve_asset_path: string;
  update_item: StoredLibraryItemDetail | null;
  archive_item: StoredLibraryItemDetail | null;
  delete_item: void;
  export_library: LibraryExportReport;
  import_library: LibraryImportReport;
  get_jobs_for_items: ProcessingJob[];
  count_active_jobs: number;
  get_onboarding_state: { shouldAutoShow: boolean };
  complete_onboarding: void;
  enqueue_ocr_job: string;
  retry_processing_job: boolean;
  get_capture_status: CaptureStatus;
  get_pairing_token: string;
  regenerate_pairing_token: string;
  select_library_directory: string | null;
  // The renderer validates each link itself before it acts on one.
  "plugin:deep-link|get_current": unknown[];
};

import { randomUUID } from "node:crypto";
import { Context, Effect, PubSub } from "effect";
import { SqlClient } from "effect/sql";
import type { ProcessingJob } from "@inkling/contracts";
import { storageFailure } from "./errors.ts";

export const JOB_LEASE_MILLIS = 5 * 60 * 1000;
export const PDF_THUMBNAIL_JOB = "pdf_thumbnail";
export const IMAGE_PALETTE_JOB = "image_palette";
export const IMAGE_THUMBNAIL_JOB = "image_thumbnail";
export const VIDEO_POSTER_JOB = "video_poster";
export const URL_ENRICHMENT_JOB = "enrich_url";
const SILENT_JOB_KINDS = new Set([
  PDF_THUMBNAIL_JOB,
  IMAGE_PALETTE_JOB,
  IMAGE_THUMBNAIL_JOB,
  VIDEO_POSTER_JOB,
]);
const silentKindsSql = [...SILENT_JOB_KINDS].map((kind) => `'${kind}'`).join(", ");

type JobRow = {
  id: string;
  item_id: string;
  kind: string;
  status: string;
  retry_count: number;
  max_retries: number;
  error_message: string | null;
  created_at: number;
  started_at: number | null;
  completed_at: number | null;
  progress_current: number;
  progress_total: number | null;
  progress_message: string | null;
};

type JobOwner = { item_id: string; kind: string };

export type Job = ProcessingJob;

function jobFromRow(row: JobRow): Job {
  return {
    id: row.id,
    itemId: row.item_id,
    kind: row.kind as Job["kind"],
    status: row.status as Job["status"],
    retryCount: row.retry_count,
    maxRetries: row.max_retries,
    errorMessage: row.error_message,
    createdAt: row.created_at,
    startedAt: row.started_at,
    completedAt: row.completed_at,
    progressCurrent: row.progress_current,
    progressTotal: row.progress_total,
    progressMessage: row.progress_message,
  };
}

const changes = (result: unknown) => (result as { changes: number }).changes;

export type JobQueueOptions = {
  now?: () => number;
  onUpdated?: (itemId: string) => void;
};

export const makeJobQueue = Effect.fnUntraced(function* ({
  now = Date.now,
  onUpdated = () => {},
}: JobQueueOptions = {}) {
  const sql = yield* SqlClient.SqlClient;
  // Workers listen here for newly queued kinds, so capture never waits for a poll.
  const enqueued = yield* PubSub.unbounded<string>();

  const notify = (itemId: string) => Effect.sync(() => onUpdated(itemId));
  const announce = (job: JobOwner | undefined) =>
    job && !SILENT_JOB_KINDS.has(job.kind) ? notify(job.item_id) : Effect.void;
  const owned = (jobId: string, workerId: string) =>
    sql<JobOwner>`SELECT item_id, kind FROM jobs
      WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}`.pipe(
      Effect.map((rows) => rows[0]),
    );

  // Inside a transaction the announcement waits for its commit, and a rollback drops it.
  const enqueue = Effect.fnUntraced(function* (itemId: string, kind: string) {
    const [existing] = yield* sql<{ id: string }>`SELECT id FROM jobs
      WHERE item_id = ${itemId} AND kind = ${kind} AND status IN ('pending', 'processing')
      ORDER BY CASE status WHEN 'pending' THEN 0 ELSE 1 END, created_at DESC LIMIT 1`;
    if (existing) return existing.id;
    const id = randomUUID();
    yield* sql`INSERT INTO jobs (id, item_id, kind, status, created_at)
      VALUES (${id}, ${itemId}, ${kind}, 'pending', ${now()})`;
    yield* sql.afterCommit(
      Effect.andThen(announce({ item_id: itemId, kind }), PubSub.publish(enqueued, kind)),
    );
    return id;
  });

  // Only each item's latest job per kind counts toward its status. The ids go in
  // as one JSON value so a large library cannot hit SQLite's parameter limit.
  const getForItems = (itemIds: ReadonlyArray<string>) =>
    itemIds.length === 0
      ? Effect.succeed([] as Job[])
      : sql<JobRow>`SELECT * FROM (
          SELECT *, ROW_NUMBER() OVER (PARTITION BY item_id, kind ORDER BY created_at DESC) AS rank
          FROM jobs WHERE item_id IN (SELECT value FROM json_each(${JSON.stringify(itemIds)}))
          AND kind NOT IN (${sql.literal(silentKindsSql)})
        ) WHERE rank = 1 ORDER BY created_at DESC`.pipe(Effect.map((rows) => rows.map(jobFromRow)));

  const getForItem = (itemId: string) =>
    sql<JobRow>`SELECT * FROM jobs WHERE item_id = ${itemId}
      AND kind NOT IN (${sql.literal(silentKindsSql)}) ORDER BY created_at DESC`.pipe(
      Effect.map((rows) => rows.map(jobFromRow)),
    );

  const countActive = sql<{ count: number }>`SELECT COUNT(*) AS count FROM jobs
    WHERE status IN ('pending', 'processing') AND kind NOT IN (${sql.literal(silentKindsSql)})`.pipe(
    Effect.map((rows) => rows[0].count),
  );

  const enqueueOcr = Effect.fnUntraced(function* (itemId: string) {
    const [item] = yield* sql<{ kind: string }>`SELECT kind FROM items WHERE id = ${itemId}`;
    if (!item) return yield* storageFailure("item not found");
    const kind = item.kind === "image" ? "ocr_image" : item.kind === "pdf" ? "ocr_pdf_page" : null;
    if (!kind) return yield* storageFailure("OCR is only available for image and PDF items");
    return yield* enqueue(itemId, kind);
  });

  const claimNext = Effect.fnUntraced(function* (
    workerId: string,
    kinds: ReadonlyArray<string> | null = null,
  ) {
    if (kinds && kinds.length === 0) return null;
    const kindFilter = kinds ? sql`AND kind IN ${sql.in(kinds)}` : sql.literal("");
    const claimed = yield* sql.withTransaction(
      Effect.gen(function* () {
        const [row] = yield* sql<JobRow>`SELECT * FROM jobs WHERE status = 'pending' ${kindFilter}
          ORDER BY created_at ASC LIMIT 1`;
        if (!row) return null;
        const startedAt = now();
        const updated = yield* sql`UPDATE jobs SET status = 'processing', started_at = ${startedAt},
          worker_id = ${workerId}, lease_until = ${startedAt + JOB_LEASE_MILLIS},
          progress_current = 0, progress_message = NULL
          WHERE id = ${row.id} AND status = 'pending'`.raw;
        return changes(updated) ? row : null;
      }),
    );
    if (!claimed) return null;
    yield* announce(claimed);
    const [row] = yield* sql<JobRow>`SELECT * FROM jobs WHERE id = ${claimed.id}`;
    return row ? jobFromRow(row) : null;
  });

  const renew = Effect.fnUntraced(function* (jobId: string, workerId: string) {
    const updated = yield* sql`UPDATE jobs SET lease_until = ${now() + JOB_LEASE_MILLIS}
      WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}`.raw;
    if (!changes(updated)) return false;
    const [job] = yield* sql<JobOwner>`SELECT item_id, kind FROM jobs WHERE id = ${jobId}`;
    yield* announce(job);
    return true;
  });

  const complete = Effect.fnUntraced(function* (jobId: string, workerId: string) {
    const job = yield* owned(jobId, workerId);
    if (!job) return false;
    const completedAt = now();
    const updated = yield* sql`UPDATE jobs SET status = 'completed', completed_at = ${completedAt},
      error_message = NULL, started_at = COALESCE(started_at, ${completedAt}), worker_id = NULL,
      lease_until = NULL, progress_current = COALESCE(progress_total, progress_current),
      progress_message = NULL
      WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}`.raw;
    if (!changes(updated)) return false;
    yield* announce(job);
    return true;
  });

  const fail = Effect.fnUntraced(function* (jobId: string, workerId: string, error: string) {
    const job = yield* owned(jobId, workerId);
    if (!job) return false;
    yield* sql.withTransaction(
      Effect.gen(function* () {
        const failedAt = now();
        const retrying = yield* sql`UPDATE jobs SET error_message = ${error},
          started_at = COALESCE(started_at, ${failedAt})
          WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}
          AND retry_count < max_retries`.raw;
        if (changes(retrying)) {
          yield* sql`UPDATE jobs SET status = 'pending', retry_count = retry_count + 1,
            worker_id = NULL, lease_until = NULL, progress_current = 0, progress_message = NULL
            WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}`;
        } else {
          yield* sql`UPDATE jobs SET status = 'failed', completed_at = ${failedAt},
            error_message = ${error}, progress_message = ${error}, worker_id = NULL,
            lease_until = NULL
            WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}`;
        }
      }),
    );
    yield* announce(job);
    return true;
  });

  // Hands an interrupted job back untouched, so quitting mid-job costs no retry.
  const release = Effect.fnUntraced(function* (jobId: string, workerId: string) {
    const job = yield* owned(jobId, workerId);
    if (!job) return false;
    yield* sql`UPDATE jobs SET status = 'pending', started_at = NULL, worker_id = NULL,
      lease_until = NULL, progress_current = 0, progress_message = NULL
      WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}`;
    yield* announce(job);
    yield* PubSub.publish(enqueued, job.kind);
    return true;
  });

  const updateProgress = Effect.fnUntraced(function* (
    jobId: string,
    workerId: string,
    current: number,
    total: number | null = null,
    message: string | null = null,
  ) {
    const job = yield* owned(jobId, workerId);
    if (!job) return false;
    const progressCurrent = Math.max(0, Number(current) || 0);
    const progressTotal = total == null ? null : Math.max(progressCurrent, Number(total) || 0);
    const updated = yield* sql`UPDATE jobs SET progress_current = ${progressCurrent},
      progress_total = ${progressTotal}, progress_message = ${message == null ? null : String(message)}
      WHERE id = ${jobId} AND status = 'processing' AND worker_id = ${workerId}`.raw;
    if (!changes(updated)) return false;
    yield* announce(job);
    return true;
  });

  const retry = Effect.fnUntraced(function* (jobId: string) {
    const [job] = yield* sql<JobOwner>`SELECT item_id, kind FROM jobs
      WHERE id = ${jobId} AND status = 'failed'`;
    if (!job) return false;
    const updated = yield* sql`UPDATE jobs SET status = 'pending', error_message = NULL,
      started_at = NULL, completed_at = NULL, worker_id = NULL, lease_until = NULL,
      retry_count = 0, progress_current = 0, progress_message = NULL
      WHERE id = ${jobId} AND status = 'failed'`.raw;
    if (!changes(updated)) return false;
    yield* announce(job);
    yield* PubSub.publish(enqueued, job.kind);
    return true;
  });

  const requeue = (condition: ReturnType<typeof sql.literal> | ReturnType<typeof sql>) =>
    Effect.gen(function* () {
      const rows = yield* sql.withTransaction(
        Effect.gen(function* () {
          const rows = yield* sql<JobOwner>`SELECT item_id, kind FROM jobs
            WHERE status = 'processing' AND ${condition}`;
          if (rows.length === 0) return rows;
          yield* sql`UPDATE jobs SET status = 'pending', started_at = NULL, error_message = NULL,
            worker_id = NULL, lease_until = NULL, progress_current = 0, progress_message = NULL
            WHERE status = 'processing' AND ${condition}`;
          return rows;
        }),
      );
      yield* Effect.forEach(rows, announce, { discard: true });
      return rows.length;
    });

  // The app holds a single-instance lock, so at startup every processing job
  // belongs to a process that is gone and can be handed back right away.
  const recoverAfterExclusiveStartup = requeue(sql.literal("1 = 1"));

  const recoverExpired = Effect.suspend(() => {
    const expiry = now();
    return requeue(sql`(lease_until IS NULL OR lease_until <= ${expiry})`);
  });

  return {
    notify,
    enqueued,
    enqueue,
    getForItems,
    getForItem,
    countActive,
    enqueueOcr,
    claimNext,
    renew,
    complete,
    fail,
    release,
    updateProgress,
    retry,
    recoverAfterExclusiveStartup,
    recoverExpired,
  };
});

export class JobQueue extends Context.Service<
  JobQueue,
  Effect.Success<ReturnType<typeof makeJobQueue>>
>()("inkling/storage/JobQueue") {}

import { Effect } from "effect";
import type { SqlClient } from "effect/sql/SqlClient";
import type { Fragment } from "effect/sql/Statement";
import type { JobQueue } from "./jobs.ts";
import { cardFromRow, detailColumns, type ItemRow, itemColumns, itemFromRow } from "./shared.ts";

export type Thumbnail = { bytes: Uint8Array; width?: number | null; height?: number | null };

export type StorageMedia = {
  createThumbnail?: (bytes: Buffer) => Promise<Thumbnail>;
  inspectImage?: (bytes: Buffer) => Promise<{ width: number; height: number } | null | undefined>;
  createSnapshot?: (source: string, destination: string) => Promise<void>;
};

export type StorageContext = {
  sql: SqlClient;
  jobs: JobQueue["Service"];
  databasePath: string;
  assetsRoot: string;
  assetsDirectory: string;
  fts5Enabled: boolean;
  media: StorageMedia;
};

export const selectCards = (
  { sql }: StorageContext,
  where: Fragment,
  limit: number | null = null,
) =>
  sql<ItemRow>`SELECT ${sql.literal(itemColumns)} FROM items WHERE ${where}
    ORDER BY updated_at DESC, created_at DESC ${limit == null ? sql.literal("") : sql`LIMIT ${limit}`}`.pipe(
    Effect.map((rows) => rows.map(cardFromRow)),
  );

export const readItem = ({ sql }: StorageContext, id: string) =>
  sql<ItemRow>`SELECT ${sql.literal(detailColumns)} FROM items WHERE id = ${id}`.pipe(
    Effect.map(([row]) => (row ? itemFromRow(row) : null)),
  );

export const changes = (result: unknown) => (result as { changes: number }).changes;

