import { mkdtemp, rename, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { Effect } from "effect";
import { readItem, type StorageContext } from "./context.ts";
import { attempt, invalidInput, itemNotFound, storageFailure } from "./errors.ts";
import {
  IMAGE_PALETTE_JOB,
  PDF_THUMBNAIL_JOB,
  URL_ENRICHMENT_JOB,
  VIDEO_POSTER_JOB,
} from "./jobs.ts";
import { changes, isMetadata, nonEmpty, normalizeHttpUrl, parseJson } from "./shared.ts";

export type UrlArticle = {
  canonicalUrl?: unknown;
  title?: unknown;
  text?: unknown;
  description?: unknown;
  html?: unknown;
  author?: unknown;
  publishedDate?: unknown;
  extractor?: unknown;
  imageUrls?: unknown;
  imageDimensions?: unknown;
  safeEmbeds?: unknown;
  social?: unknown;
};

type Candidate = { rowid: number; id: string };

// Exported so a test can check the query plan walks the kind index without sorting.
export const pdfThumbnailCandidateSql = `SELECT rowid, id FROM items
  WHERE kind = 'pdf' AND rowid > ? AND thumbnail_path IS NULL AND local_asset_path != ''
  AND NOT EXISTS (SELECT 1 FROM jobs WHERE item_id = items.id AND kind = ? AND status = 'failed')
  ORDER BY rowid LIMIT 1`;

const videoPosterCandidateSql = `SELECT rowid, id FROM items
  WHERE kind = 'video' AND rowid > ? AND thumbnail_path IS NULL AND local_asset_path != ''
  AND NOT EXISTS (SELECT 1 FROM jobs WHERE item_id = items.id AND kind = ? AND status = 'failed')
  ORDER BY rowid LIMIT 1`;

const imagePaletteCandidateSql = `SELECT rowid, id FROM items
  WHERE kind = 'image' AND thumbnail_path IS NOT NULL AND rowid > ?
  AND NOT EXISTS (SELECT 1 FROM jobs WHERE item_id = items.id AND kind = ? AND status = 'failed')
  AND json_type(metadata, '$.palette') IS NULL
  ORDER BY rowid LIMIT 1`;

export function makeEnrichment(ctx: StorageContext) {
  const { sql, jobs } = ctx;
  const candidate = (query: string, afterRowid: number, kind: string) =>
    sql.unsafe<Candidate>(query, [afterRowid, kind]).pipe(Effect.map(([row]) => row));

  const storeOcrText = Effect.fnUntraced(function* (id: string, text: string, engine: string) {
    const [row] = yield* sql<{ metadata: string }>`SELECT metadata FROM items WHERE id = ${id}`;
    if (!row) return yield* itemNotFound(id);
    const parsed = parseJson<unknown>(row.metadata, {});
    const metadata = isMetadata(parsed) ? parsed : {};
    delete metadata.ocrText;
    metadata.ocrEngine = String(engine);
    metadata.ocrCompletedAt = Date.now();
    // Leaves updated_at alone: the library sorts by it, and background OCR
    // finishing should not move a card the user did not touch.
    yield* sql`UPDATE items SET ocr_text = ${String(text)}, metadata = ${JSON.stringify(metadata)}
      WHERE id = ${id}`;
  });

  const applyUrlEnrichment = Effect.fnUntraced(function* (
    jobId: string,
    workerId: string,
    article: UrlArticle = {},
  ) {
    const canonicalUrl = yield* normalizeHttpUrl(article.canonicalUrl ?? "");
    const articleTitle = nonEmpty(article.title);
    const text = nonEmpty(article.text) ?? "";
    const description = nonEmpty(article.description) ?? (text ? text.slice(0, 180) : null);
    const html = nonEmpty(article.html);
    const author = nonEmpty(article.author);
    const publishedDate = nonEmpty(article.publishedDate);
    const extractor = nonEmpty(article.extractor);
    const sourceLabel = new URL(canonicalUrl).hostname;

    return yield* sql.withTransaction(
      Effect.gen(function* () {
        const [job] = yield* sql<{ item_id: string }>`SELECT item_id FROM jobs WHERE id = ${jobId}
          AND kind = ${URL_ENRICHMENT_JOB} AND status = 'processing' AND worker_id = ${workerId}`;
        if (!job) return false;
        const item = yield* readItem(ctx, job.item_id);
        if (!item) return false;

        const metadata = { ...item.metadata };
        const pending = metadata.pendingUrlCapture;
        const shouldUseArticleTitle =
          isMetadata(pending) &&
          pending.preserveTitle !== true &&
          item.title === pending.initialTitle;
        delete metadata.pendingUrlCapture;
        metadata.sourceUrl = canonicalUrl;
        if (text) {
          metadata.text = text;
          metadata.extractedText = text;
        }
        if (html) metadata.html = html;
        if (author) metadata.author = author;
        if (publishedDate) metadata.publishedDate = publishedDate;
        if (extractor) metadata.extractor = extractor;
        for (const key of ["imageUrls", "imageDimensions", "safeEmbeds"] as const) {
          const values = article[key];
          if (Array.isArray(values) && values.length > 0) metadata[key] = values;
        }
        if (article.social) metadata.social = article.social;

        yield* sql`UPDATE items SET
          title = ${shouldUseArticleTitle ? (articleTitle ?? item.title) : item.title},
          description = ${nonEmpty(item.description) ? item.description : description},
          source_url = ${canonicalUrl}, source_label = ${sourceLabel},
          metadata = ${JSON.stringify(metadata)}, updated_at = ${Date.now()}
          WHERE id = ${item.id}`;
        yield* jobs.enqueue(item.id, "generate_embedding");
        return true;
      }),
    );
  });

  // Kinds whose thumbnail is rendered after capture, so the stored row may still
  // be waiting for one. An existing thumbnail is never replaced.
  const storeDerivedThumbnail = Effect.fnUntraced(function* (
    id: string,
    kind: string,
    png: Buffer,
    recordSize = false,
  ) {
    const pending = sql`SELECT 1 FROM items WHERE id = ${id} AND kind = ${kind}
      AND thumbnail_path IS NULL`.pipe(Effect.map((rows) => rows.length > 0));
    if (!(yield* pending)) return false;
    const createThumbnail = ctx.media.createThumbnail;
    if (!createThumbnail) return yield* storageFailure("image thumbnail generation is unavailable");
    const thumbnail = yield* attempt(() => createThumbnail(png));
    return yield* Effect.acquireUseRelease(
      attempt(() => mkdtemp(join(dirname(ctx.databasePath), ".inkling-thumbnail-"))),
      Effect.fnUntraced(function* (staging) {
        const staged = join(staging, "thumbnail.webp");
        yield* attempt(() => writeFile(staged, thumbnail.bytes));
        if (!(yield* pending)) return false;
        yield* attempt(() => rename(staged, join(ctx.assetsDirectory, id, "thumbnail.webp")));
        const updated = yield* sql`UPDATE items SET
          thumbnail_path = ${`assets/items/${id}/thumbnail.webp`},
          metadata = CASE WHEN ${Number(recordSize)}
            THEN json_set(metadata, '$.mediaWidth', ${thumbnail.width ?? null},
              '$.mediaHeight', ${thumbnail.height ?? null})
            ELSE metadata END
          WHERE id = ${id} AND kind = ${kind} AND thumbnail_path IS NULL`.raw;
        if (changes(updated)) yield* jobs.notify(id);
        return changes(updated) > 0;
      }),
      (staging) => attempt(() => rm(staging, { recursive: true, force: true })).pipe(Effect.ignore),
    );
  });

  const storeImagePalette = Effect.fnUntraced(function* (id: string, palette: unknown) {
    if (
      !Array.isArray(palette) ||
      palette.length !== 5 ||
      palette.some((color) => typeof color !== "string" || !/^#[0-9a-f]{6}$/i.test(color))
    ) {
      return yield* invalidInput("image palette must contain five hex colors");
    }
    const item = yield* readItem(ctx, id);
    if (item?.kind !== "image") return false;
    const metadata = JSON.stringify({ ...item.metadata, palette });
    const updated = yield* sql`UPDATE items SET metadata = ${metadata}
      WHERE id = ${id} AND kind = 'image'`.raw;
    if (changes(updated)) yield* jobs.notify(id);
    return changes(updated) > 0;
  });

  return {
    storeOcrText,
    applyUrlEnrichment,
    nextPdfThumbnailCandidate: (afterRowid: number) =>
      candidate(pdfThumbnailCandidateSql, afterRowid, PDF_THUMBNAIL_JOB),
    nextVideoPosterCandidate: (afterRowid: number) =>
      candidate(videoPosterCandidateSql, afterRowid, VIDEO_POSTER_JOB),
    nextImagePaletteCandidate: (afterRowid: number) =>
      candidate(imagePaletteCandidateSql, afterRowid, IMAGE_PALETTE_JOB),
    storePdfThumbnail: (id: string, png: Buffer) => storeDerivedThumbnail(id, "pdf", png),
    storeVideoPoster: (id: string, png: Buffer) => storeDerivedThumbnail(id, "video", png),
    // The decoded size also lands in the metadata: BMP and ICO captures have no
    // header-only size, and an EXIF-rotated photo needs its oriented one.
    storeImageThumbnail: (id: string, bytes: Buffer) =>
      storeDerivedThumbnail(id, "image", bytes, true),
    storeImagePalette,
  };
}

import { Effect } from "effect";
import type { StoredLibraryCard } from "@inkling/contracts";
import { IMAGE_MODEL, TEXT_MODEL } from "../embedding-contract.ts";
import { selectCards, type StorageContext } from "./context.ts";
import { invalidInput } from "./errors.ts";
import {
  cardItem,
  clampLimit,
  type ItemRow,
  itemColumns,
  itemFromRow,
  qualifiedItemColumns,
} from "./shared.ts";

const semanticMatchFloor = 0.55;

type EmbeddingRow = ItemRow & { embedding_dimension: number; embedding_vector: Uint8Array };

export type QueryVector = ArrayLike<number> | null | undefined;

export function escapeFtsQuery(query: string) {
  return query
    .split(/\s+/)
    .filter(Boolean)
    .map((token) => `"${token.replaceAll('"', "")}"`)
    .filter((token) => token !== '""')
    .join(" ");
}

function decodeFloatVector(blob: Uint8Array | null, dimension: number) {
  if (!blob || blob.byteLength !== dimension * 4) return null;
  const bytes = Buffer.from(blob.buffer, blob.byteOffset, blob.byteLength);
  return Array.from({ length: dimension }, (_, index) => bytes.readFloatLE(index * 4));
}

function dotProduct(left: ArrayLike<number>, right: ArrayLike<number>) {
  if (left.length !== right.length) return Number.NEGATIVE_INFINITY;
  let score = 0;
  for (let index = 0; index < left.length; index += 1) score += left[index] * right[index];
  return score;
}

export function sqlLikePattern(value: string) {
  return `%${value.replace(/[\\%_]/g, "\\$&")}%`;
}

export function makeSearch(ctx: StorageContext) {
  const { sql } = ctx;

  const likeClause = (pattern: string, prefix = "") => {
    const column = (name: string) =>
      sql`${sql.literal(`${prefix}${name}`)} COLLATE NOCASE LIKE ${pattern} ESCAPE char(92)`;
    return sql`(${sql.or(["title", "description", "body", "source_label", "ocr_text", "metadata"].map(column))})`;
  };

  const storeEmbedding = Effect.fnUntraced(function* (
    itemId: string,
    kind: string,
    model: string,
    bytes: Uint8Array,
    dimension: number,
  ) {
    if (kind !== "text" && kind !== "image") {
      return yield* invalidInput("embedding kind must be text or image");
    }
    const vector = Buffer.from(bytes);
    if (!Number.isInteger(dimension) || dimension < 1 || vector.length !== dimension * 4) {
      return yield* invalidInput("embedding vector dimension does not match its bytes");
    }
    yield* sql`INSERT INTO item_embeddings (item_id, kind, model, dimension, vector, created_at)
      VALUES (${itemId}, ${kind}, ${String(model)}, ${dimension}, ${vector}, ${Date.now()})
      ON CONFLICT(item_id, kind) DO UPDATE SET model = excluded.model,
      dimension = excluded.dimension, vector = excluded.vector, created_at = excluded.created_at`;
  });

  const searchItems = Effect.fnUntraced(function* (
    query: unknown,
    limit: unknown = 100,
    queryVector: QueryVector = null,
  ) {
    const search = String(query ?? "").trim();
    const cap = clampLimit(limit, 100, 200);
    if (!search) return yield* selectCards(ctx, sql`archived = 0`, cap);
    let rows: ReadonlyArray<ItemRow> = [];
    if (ctx.fts5Enabled) {
      const match = escapeFtsQuery(search);
      if (match) {
        rows = yield* sql<ItemRow>`SELECT ${sql.literal(qualifiedItemColumns)}
          FROM items_fts f JOIN items i ON i.id = f.item_id
          WHERE i.archived = 0 AND items_fts MATCH ${match}
          ORDER BY i.updated_at DESC, i.created_at DESC LIMIT ${cap}`;
      }
    } else {
      rows = yield* sql<ItemRow>`SELECT ${sql.literal(itemColumns)} FROM items
        WHERE archived = 0 AND ${likeClause(sqlLikePattern(search))}
        ORDER BY updated_at DESC, created_at DESC LIMIT ${cap}`;
    }
    const lexicalItems = rows.map(itemFromRow);
    if (!queryVector?.length) return lexicalItems.map(cardItem);

    const ranked = new Map(lexicalItems.map((item) => [item.id, { item, score: 2 }]));
    const candidates = yield* sql<EmbeddingRow>`SELECT ${sql.literal(qualifiedItemColumns)},
      e.dimension AS embedding_dimension, e.vector AS embedding_vector
      FROM item_embeddings e JOIN items i ON i.id = e.item_id
      WHERE i.archived = 0 AND ((e.kind = 'text' AND e.model = ${TEXT_MODEL})
        OR (e.kind = 'image' AND e.model = ${IMAGE_MODEL}))`;
    for (const row of candidates) {
      const vector = decodeFloatVector(row.embedding_vector, row.embedding_dimension);
      if (!vector || vector.length !== queryVector.length) continue;
      const item = itemFromRow(row);
      const similarity = dotProduct(queryVector, vector);
      const current = ranked.get(item.id);
      if (similarity < semanticMatchFloor && !current) continue;
      const score = current ? 2 + Math.max(similarity, 0) : similarity;
      if (current) current.score = Math.max(current.score, score);
      else ranked.set(item.id, { item, score });
    }

    return [...ranked.values()]
      .sort((left, right) => right.score - left.score || right.item.updatedAt - left.item.updatedAt)
      .slice(0, cap)
      .map(({ item }) => cardItem(item));
  });

  const searchSimilar = Effect.fnUntraced(function* (
    itemId: string,
    kind: "image" | "text",
    limit: unknown = 12,
  ) {
    const model = kind === "image" ? IMAGE_MODEL : TEXT_MODEL;
    const [source] = yield* sql<{ dimension: number; vector: Uint8Array }>`SELECT dimension, vector
      FROM item_embeddings WHERE item_id = ${itemId} AND kind = ${kind} AND model = ${model}`;
    if (!source) return [] as StoredLibraryCard[];
    const sourceVector = decodeFloatVector(source.vector, source.dimension);
    if (!sourceVector)
      return yield* invalidInput(`stored ${kind} embedding dimension does not match its vector`);
    const kinds =
      kind === "image" ? sql`i.kind = 'image'` : sql`i.kind IN ('article', 'url', 'note', 'quote')`;
    const candidates = yield* sql<EmbeddingRow>`SELECT ${sql.literal(qualifiedItemColumns)},
      e.dimension AS embedding_dimension, e.vector AS embedding_vector
      FROM item_embeddings e JOIN items i ON i.id = e.item_id
      WHERE i.archived = 0 AND i.id != ${itemId} AND ${kinds}
      AND e.kind = ${kind} AND e.model = ${model}`;
    return candidates
      .flatMap((row) => {
        const vector = decodeFloatVector(row.embedding_vector, row.embedding_dimension);
        return vector && vector.length === sourceVector.length
          ? [{ item: itemFromRow(row), score: dotProduct(sourceVector, vector) }]
          : [];
      })
      .sort((left, right) => right.score - left.score)
      .slice(0, clampLimit(limit, 12, 50))
      .map(({ item }) => cardItem(item));
  });

  return { storeEmbedding, searchItems, searchSimilar, likeClause };
}

import { randomUUID } from "node:crypto";
import { Effect } from "effect";
import type {
  CreateSpaceInput,
  SmartSpaceQuery,
  SpaceColor,
  StoredSpace,
  UpdateSpaceInput,
} from "@inkling/contracts";
import type { Fragment } from "effect/sql/Statement";
import { readItem, type StorageContext } from "./context.ts";
import { invalidInput, itemNotFound, spaceNotFound } from "./errors.ts";
import type { QueryVector } from "./search.ts";
import { escapeFtsQuery, type makeSearch, sqlLikePattern } from "./search.ts";
import {
  cardFromRow,
  changes,
  clampLimit,
  type ItemRow,
  isMetadata,
  nonEmpty,
  parseJson,
  qualifiedItemColumns,
} from "./shared.ts";

type SpaceRow = {
  id: string;
  name: string;
  color: SpaceColor;
  query: string;
  kind: StoredSpace["kind"];
  position: number;
  created_at: number;
  updated_at: number;
  item_count?: number | null;
};

const spaceColors = ["blue", "orange", "green", "pink", "purple", "yellow"] as const;

function spaceFromRow(row: SpaceRow): StoredSpace {
  return {
    id: row.id,
    name: row.name,
    color: row.color,
    query: parseJson<SmartSpaceQuery>(row.query, {}),
    kind: row.kind,
    position: row.position,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    ...(row.kind === "regular" && row.item_count != null
      ? { itemCount: Number(row.item_count) }
      : {}),
  };
}

export const validateSmartQuery = Effect.fnUntraced(function* (query: unknown = {}) {
  if (!isMetadata(query)) return yield* invalidInput("Space query must be an object");
  const clean = Effect.fnUntraced(function* (value: unknown, field: string, max: number) {
    if (value == null) return undefined;
    if (typeof value !== "string") return yield* invalidInput(`${field} must be text`);
    const trimmed = value.trim();
    if (Buffer.byteLength(trimmed) > max)
      return yield* invalidInput(`${field} must be at most ${max} characters`);
    return trimmed || undefined;
  });
  return {
    text: yield* clean(query.text, "text", 512),
    kind: yield* clean(query.kind, "kind", 32),
    tag: yield* clean(query.tag, "tag", 64),
  };
});

const normalizeSpaceName = Effect.fnUntraced(function* (name: unknown) {
  const normalized = String(name ?? "").trim();
  if (!normalized) return yield* invalidInput("space name cannot be empty");
  if (Buffer.byteLength(normalized) > 80)
    return yield* invalidInput("space name must be at most 80 characters");
  return normalized;
});

export function normalizeSpaceColor(color: unknown): SpaceColor {
  const normalized = nonEmpty(color)?.toLowerCase();
  return spaceColors.find((value) => value === normalized) ?? "blue";
}

export function makeSpaces(ctx: StorageContext, search: ReturnType<typeof makeSearch>) {
  const { sql } = ctx;

  const listSpaces = () =>
    sql<SpaceRow>`SELECT spaces.*, membership.item_count FROM spaces
      LEFT JOIN (
        SELECT space_id, COUNT(*) AS item_count FROM space_items GROUP BY space_id
      ) membership ON membership.space_id = spaces.id
      ORDER BY spaces.position, spaces.created_at`.pipe(
      Effect.map((rows) => rows.map(spaceFromRow)),
    );

  const getSpace = (id: string) =>
    sql<SpaceRow>`SELECT * FROM spaces WHERE id = ${id}`.pipe(
      Effect.map(([row]) => (row ? spaceFromRow(row) : null)),
    );

  const createSpace = Effect.fnUntraced(function* (input: CreateSpaceInput) {
    const name = yield* normalizeSpaceName(input.name);
    const kind = input.kind ?? "smart";
    if (kind !== "smart" && kind !== "regular")
      return yield* invalidInput("Space kind must be smart or regular");
    const query = kind === "regular" ? {} : yield* validateSmartQuery(input.query);
    const id = randomUUID();
    const now = Date.now();
    const [{ next }] = yield* sql<{ next: number }>`SELECT COALESCE(MAX(position), 0) + 1 AS next
      FROM spaces`;
    yield* sql`INSERT INTO spaces (id, name, color, query, kind, position, created_at, updated_at)
      VALUES (${id}, ${name}, ${normalizeSpaceColor(input.color)}, ${JSON.stringify(query)}, ${kind},
      ${next}, ${now}, ${now})`;
    return yield* getSpace(id);
  });

  const updateSpace = Effect.fnUntraced(function* (input: UpdateSpaceInput) {
    if (input.query != null) {
      const space = yield* getSpace(input.id);
      if (space?.kind === "regular")
        return yield* invalidInput("a Regular Space has no search query to change");
      if (!space) return yield* spaceNotFound(input.id);
    }
    const query = input.query == null ? null : JSON.stringify(yield* validateSmartQuery(input.query));
    const name = input.name == null ? null : yield* normalizeSpaceName(input.name);
    const color = input.color == null ? null : normalizeSpaceColor(input.color);
    const updated = yield* sql`UPDATE spaces SET name = COALESCE(${name}, name),
      color = COALESCE(${color}, color), query = COALESCE(${query}, query),
      position = COALESCE(${input.position ?? null}, position), updated_at = ${Date.now()}
      WHERE id = ${input.id}`.raw;
    if (!changes(updated)) return yield* spaceNotFound(input.id);
    return yield* getSpace(input.id);
  });

  const deleteSpace = (id: string) =>
    sql.withTransaction(
      Effect.gen(function* () {
        yield* sql`DELETE FROM space_items WHERE space_id = ${id}`;
        const deleted = yield* sql`DELETE FROM spaces WHERE id = ${id}`.raw;
        if (!changes(deleted)) return yield* spaceNotFound(id);
      }),
    );

  const swapSpacePositions = Effect.fnUntraced(function* (firstId: string, secondId: string) {
    if (firstId === secondId) {
      if (!(yield* getSpace(firstId))) return yield* spaceNotFound(firstId);
      return yield* listSpaces();
    }
    const rows = yield* sql<{ id: string; position: number }>`SELECT id, position FROM spaces
      WHERE id IN (${firstId}, ${secondId})`;
    const first = rows.find((row) => row.id === firstId);
    const second = rows.find((row) => row.id === secondId);
    if (!first) return yield* spaceNotFound(firstId);
    if (!second) return yield* spaceNotFound(secondId);
    yield* sql`UPDATE spaces SET position = CASE id WHEN ${firstId} THEN ${second.position}
      WHEN ${secondId} THEN ${first.position} ELSE position END, updated_at = ${Date.now()}
      WHERE id IN (${firstId}, ${secondId})`;
    return yield* listSpaces();
  });

  // SQLite's lower() folds ASCII only, so tags compare in JavaScript and the
  // matching ids go back in as one JSON value.
  const taggedItemIds = (tag: string) =>
    sql<{ id: string; tag: string }>`SELECT i.id, t.value AS tag
      FROM items i, json_each(i.metadata, '$.tags') t
      WHERE i.archived = 0 AND t.type = 'text'`.pipe(
      Effect.map((rows) => {
        const wanted = tag.toLowerCase();
        return JSON.stringify([
          ...new Set(rows.filter((row) => row.tag.toLowerCase() === wanted).map((row) => row.id)),
        ]);
      }),
    );

  const listSpaceItems = Effect.fnUntraced(function* (
    id: string,
    limit: unknown = 100,
    queryVector: QueryVector = null,
  ) {
    const space = yield* getSpace(id);
    if (!space) return yield* spaceNotFound(id);
    const cap = clampLimit(limit, 100, 200);
    if (space.kind === "regular") {
      const rows = yield* sql<ItemRow>`SELECT ${sql.literal(qualifiedItemColumns)}
        FROM space_items s JOIN items i ON i.id = s.item_id
        WHERE s.space_id = ${id} AND i.archived = 0 ORDER BY s.added_at DESC, i.id LIMIT ${cap}`;
      return rows.map(cardFromRow);
    }
    const query = space.query;
    const text = nonEmpty(query.text);
    const clauses: Fragment[] = [sql`i.archived = 0`];
    let from = sql.literal("items i");
    let rankedCandidates: ReturnType<typeof cardFromRow>[] | null = null;
    if (text && queryVector?.length) {
      rankedCandidates = yield* search.searchItems(text, 200, queryVector);
      if (!rankedCandidates.length) return [];
      const ids = JSON.stringify(rankedCandidates.map((item) => item.id));
      clauses.push(sql`i.id IN (SELECT value FROM json_each(${ids}))`);
    } else if (text && ctx.fts5Enabled) {
      const match = escapeFtsQuery(text);
      if (!match) return [];
      from = sql.literal("items_fts f JOIN items i ON i.id = f.item_id");
      clauses.push(sql`items_fts MATCH ${match}`);
    } else if (text) {
      clauses.push(search.likeClause(sqlLikePattern(text), "i."));
    }
    const tag = nonEmpty(query.tag);
    if (tag) clauses.push(sql`i.id IN (SELECT value FROM json_each(${yield* taggedItemIds(tag)}))`);
    const kind = nonEmpty(query.kind);
    if (kind) {
      clauses.push(
        kind.toLowerCase() === "article"
          ? sql`i.kind IN ('url', 'article')`
          : sql`lower(i.kind) = lower(${kind})`,
      );
    }
    const rows = yield* sql<ItemRow>`SELECT ${sql.literal(qualifiedItemColumns)} FROM ${from}
      WHERE ${sql.and(clauses)} ORDER BY i.updated_at DESC, i.created_at DESC LIMIT ${cap}`;
    if (rankedCandidates) {
      const matchingIds = new Set(rows.map((row) => row.id));
      return rankedCandidates.filter((item) => matchingIds.has(item.id)).slice(0, cap);
    }
    return rows.map(cardFromRow);
  });

  const addSpaceItem = Effect.fnUntraced(function* (spaceId: string, itemId: string) {
    const space = yield* getSpace(spaceId);
    if (!space) return yield* spaceNotFound(spaceId);
    if (space.kind !== "regular")
      return yield* invalidInput("items can only be added to a Regular Space");
    if (!(yield* readItem(ctx, itemId))) return yield* itemNotFound(itemId);
    yield* sql`INSERT OR IGNORE INTO space_items (space_id, item_id, added_at)
      VALUES (${spaceId}, ${itemId}, ${Date.now()})`;
  });

  const removeSpaceItem = Effect.fnUntraced(function* (spaceId: string, itemId: string) {
    if (!(yield* getSpace(spaceId))) return yield* spaceNotFound(spaceId);
    yield* sql`DELETE FROM space_items WHERE space_id = ${spaceId} AND item_id = ${itemId}`;
  });

  const listItemSpaces = (itemId: string) =>
    sql<{ id: string }>`SELECT s.id FROM space_items m JOIN spaces s ON s.id = m.space_id
      WHERE m.item_id = ${itemId} ORDER BY s.position, s.created_at`.pipe(
      Effect.map((rows) => rows.map((row) => row.id)),
    );

  return {
    listSpaces,
    getSpace,
    createSpace,
    updateSpace,
    deleteSpace,
    swapSpacePositions,
    listSpaceItems,
    addSpaceItem,
    removeSpaceItem,
    listItemSpaces,
  };
}

