  ".webm": "video/webm",
};

protocol.registerSchemesAsPrivileged([
  {
    scheme: "app",
    // stream lets <video> and <audio> issue Range requests against the asset handler.
    privileges: {
      standard: true,
      secure: true,
      supportFetchAPI: true,
      corsEnabled: false,
      stream: true,
    },
  },
]);

// Remote card images load with crossorigin so the liquid glass canvas can draw
// them (Chromium paints opaque cross-origin images blank). Most hosts send no
// CORS header, so the app's session adds one to image responses. The requests
// themselves are unchanged.
function allowCanvasReadableImages() {
  session.defaultSession.webRequest.onHeadersReceived(
    { urls: ["https://*/*"] },
    ({ resourceType, responseHeaders }, callback) => {
      if (resourceType !== "image") return callback({});
      const headers = Object.fromEntries(
        Object.entries(responseHeaders ?? {}).filter(
          ([name]) => name.toLowerCase() !== "access-control-allow-origin",
        ),
      );
      callback({ responseHeaders: { ...headers, "Access-Control-Allow-Origin": ["*"] } });
    },
  );
}

function sendDeepLinks(contents, links) {
  if (!contents.isDestroyed() && links.length > 0) {
    contents.send("inkling:deep-link", links);
  }
}

function enqueueDeepLink(value) {
  const capture = parseDeepLinkCaptureCore(value);
  if (!capture) return;

  const subscribers = [...deepLinkSubscribers].filter((contents) => !contents.isDestroyed());
  if (subscribers.length === 0) {
    pendingDeepLinks.push(capture);
    return;
  }
  for (const contents of subscribers) sendDeepLinks(contents, [capture]);
}

function handleDeepLinkArguments(argumentsList) {
  for (const argument of argumentsList) {
    if (argument.startsWith("inkling:")) enqueueDeepLink(argument);
  }
}

function emitJobUpdated(itemId) {
  for (const window of BrowserWindow.getAllWindows()) {
    if (!window.webContents.isDestroyed())
      window.webContents.send("inkling:job-updated", { itemId });
  }
}

function initializeLibraryStorage() {
  if (libraryStorage) return libraryStorage.status();
  libraryStorage = openLibraryStorage(join(libraryDirectory, "library.sqlite3"), {
    jobQueue: { onUpdated: emitJobUpdated },
    createSnapshot: snapshotDatabase,
    createThumbnail: (bytes) =>
      import("./thumbnail.mjs").then(({ createImageThumbnail }) => createImageThumbnail(bytes)),
    inspectImage: (bytes) =>
      import("./thumbnail.mjs").then(({ inspectImage }) => inspectImage(bytes)),
  });
  aiJobProcessors = createAiJobProcessors({
    modelCacheDirectory: join(libraryDirectory, "models"),
    bundledModelDirectory: app.isPackaged ? join(process.resourcesPath, "models") : undefined,
  });
  libraryStorage.jobs.recoverUrlEnrichmentAfterExclusiveStartup();
  enqueueStaleImageEmbeddings(libraryStorage);
  jobWorker = new JobWorker(libraryStorage, {
    processors: aiJobProcessors.processors,
    onIdle: aiJobProcessors.onIdle,
  }).start();
  thumbnailWorker = new JobWorker(libraryStorage, {
    processors: aiJobProcessors.thumbnailProcessors,
  }).start();
  return libraryStorage.status();
}

function requireLibraryStorage() {
  if (!libraryStorage) throw new Error("storage has not been initialized");
  return libraryStorage;
}

async function embedQueryForSearch(query) {
  if (!query || !aiJobProcessors) return null;
  try {
    return await aiJobProcessors.embedQuery(query);
  } catch {
    return null;
  }
}

const chooseLibraryDirectory = createSingleFlightDirectoryPicker({
  getParent: () => mainWindow,
  showOpenDialog: (parent, options) => dialog.showOpenDialog(parent, options),
});

function registerLibraryCommands() {
  const storageCommands = {
    initialize_storage: () => initializeLibraryStorage(),
    get_app_version: () => app.getVersion(),
    get_library_size: async ({ refresh = false }) => {
      initializeLibraryStorage();
      return librarySizeCache.get({ refresh: Boolean(refresh) });
    },
    get_last_export: () => requireLibraryStorage().getLastExport(),
    show_library_folder: async () => {
      const error = await shell.openPath(libraryDirectory);
      if (error) throw new Error(error);
      return true;
    },
    show_item_in_folder: async ({ id }) => {
      const item = requireLibraryStorage().getItem(id);
      if (!item?.localAssetPath) return false;
      const assetPath = await requireLibraryStorage().resolveAssetPath(item.localAssetPath);
      shell.showItemInFolder(assetPath);
      return true;
    },
    list_active_items: () => requireLibraryStorage().listActiveItems(),
    list_archived_items: () => requireLibraryStorage().listArchivedItems(),
    get_item: ({ id }) => requireLibraryStorage().getItem(id),
    get_item_cards: ({ ids }) => requireLibraryStorage().getItemCards(ids),
    get_change_count: () => requireLibraryStorage().changeCount(),
    get_item_content: ({ id }) => requireLibraryStorage().getItemContent(id),
    search_items: async ({ query, limit }) => {
      const text = String(query ?? "").trim();
      const queryVector = await embedQueryForSearch(text);
      return requireLibraryStorage().searchItems(query, limit, queryVector);
    },
    search_similar_images: ({ itemId, limit }) =>
      requireLibraryStorage().searchSimilar(itemId, "image", limit),
    search_similar_text: ({ itemId, limit }) =>
      requireLibraryStorage().searchSimilar(itemId, "text", limit),
    list_spaces: () => requireLibraryStorage().listSpaces(),
    create_space: ({ input }) => requireLibraryStorage().createSpace(input),
    delete_space: ({ id }) => requireLibraryStorage().deleteSpace(id),
    update_space: ({ input }) => requireLibraryStorage().updateSpace(input),
    swap_space_positions: ({ firstId, secondId }) =>
      requireLibraryStorage().swapSpacePositions(firstId, secondId),
    list_space_items: async ({ id, limit }) => {
      const storage = requireLibraryStorage();
      const space = storage.getSpace(id);
      const text = space?.kind === "smart" ? String(space.query.text ?? "").trim() : "";
      const queryVector = await embedQueryForSearch(text);
      return storage.listSpaceItems(id, limit, queryVector);
    },
    add_space_item: ({ spaceId, itemId }) => requireLibraryStorage().addSpaceItem(spaceId, itemId),
    remove_space_item: ({ spaceId, itemId }) =>
      requireLibraryStorage().removeSpaceItem(spaceId, itemId),
    list_item_spaces: ({ itemId }) => requireLibraryStorage().listItemSpaces(itemId),
    create_note: ({ input }) => requireLibraryStorage().createNote(input),
    create_quote: ({ input }) => requireLibraryStorage().createQuote(input),
    capture_url: ({ input }) => requireLibraryStorage().captureUrl(input),
    save_file: async ({ input }) => {
      const item = await requireLibraryStorage().saveFile(input);
      // The worker only polls every few seconds; the card is waiting on this one.
      void thumbnailWorker?.pump();
      return item;
    },
    resolve_asset_path: ({ path }) => requireLibraryStorage().resolveAssetPath(path),
    update_item: ({ input }) => requireLibraryStorage().updateItem(input),
    archive_item: ({ id, archived = true }) => requireLibraryStorage().archiveItem(id, archived),
    delete_item: ({ id }) => requireLibraryStorage().deleteItem(id),
    export_library: ({ destination, timezoneOffsetMinutes }) =>
      requireLibraryStorage().exportLibrary(destination, timezoneOffsetMinutes),
    import_library: ({ exportDirectory }) => requireLibraryStorage().importLibrary(exportDirectory),
    get_jobs_for_items: ({ itemIds }) => requireLibraryStorage().jobs.getForItems(itemIds),
    count_active_jobs: () => requireLibraryStorage().jobs.countActive(),
    get_onboarding_state: () => ({
      shouldAutoShow: app.isPackaged && !requireLibraryStorage().hasCompletedOnboarding(),
    }),
    complete_onboarding: () => requireLibraryStorage().completeOnboarding(),
    enqueue_ocr_job: ({ itemId }) => requireLibraryStorage().jobs.enqueueOcr(itemId),
    retry_processing_job: ({ jobId }) => requireLibraryStorage().jobs.retry(jobId),
    get_capture_status: () =>
      captureServer?.status() ?? { running: false, port: null, healthUrl: null },
    get_pairing_token: () => {
      if (!captureServer) throw new Error("The Electron capture server is unavailable.");
      return captureServer.getPairingToken();
    },
    regenerate_pairing_token: () => {
      if (!captureServer) throw new Error("The Electron capture server is unavailable.");
      return captureServer.regeneratePairingToken();
    },
  };

  for (const [command, handler] of Object.entries(storageCommands)) {
    ipcMain.handle(`inkling:${command}`, (_event, args = {}) => handler(args ?? {}));
  }

  ipcMain.handle("inkling:select_library_directory", (_event, { title }) =>
    chooseLibraryDirectory(title),
  );

  ipcMain.handle("inkling:check_for_updates", () => updateController.checkForUpdates());
  ipcMain.handle("inkling:install_update", (_event, { expectedVersion }) =>
    updateController.installUpdate(expectedVersion),
  );

  ipcMain.handle("inkling:plugin:deep-link|get_current", () => pendingDeepLinks.splice(0));
  ipcMain.handle("inkling:deep-link:subscribe", (event) => {
    deepLinkSubscribers.add(event.sender);
    event.sender.once("destroyed", () => deepLinkSubscribers.delete(event.sender));
    sendDeepLinks(event.sender, pendingDeepLinks.splice(0));
  });
  ipcMain.handle("inkling:deep-link:unsubscribe", (event) => {
    deepLinkSubscribers.delete(event.sender);
  });

  ipcMain.handle("inkling:window:minimize", (event) => {
    BrowserWindow.fromWebContents(event.sender)?.minimize();
  });
  ipcMain.handle("inkling:window:toggle-maximize", (event) => {
    const window = BrowserWindow.fromWebContents(event.sender);
    if (!window) return;
    if (window.isMaximized()) window.unmaximize();
    else window.maximize();
  });
  ipcMain.handle("inkling:window:close", (event) => {
    BrowserWindow.fromWebContents(event.sender)?.close();
  });
  ipcMain.handle("inkling:window:ready", (event) => {
    const window = BrowserWindow.fromWebContents(event.sender);
    if (window && !window.isVisible()) window.show();
  });
}

async function serveAppAsset(request) {
  const url = new URL(request.url);
  if (url.hostname !== "local") return new Response(null, { status: 404 });

  let requestPath;
  try {
    requestPath = decodeURIComponent(url.pathname);
  } catch {
    return new Response(null, { status: 400 });
  }
  if (requestPath === "/" || requestPath.endsWith("/")) requestPath += "index.html";

  const libraryAssetPrefix = "/library-assets/";
  const isLibraryAsset = requestPath.startsWith(libraryAssetPrefix);
  const assetDirectory = isLibraryAsset
    ? join(app.getPath("userData"), "assets")
    : app.isPackaged
      ? join(app.getAppPath(), "dist")
      : resolve(mainDirectory, "../dist");
  const relativeRequestPath = isLibraryAsset
    ? `/${requestPath.slice(libraryAssetPrefix.length)}`
    : requestPath;
  return serveAssetFile(request, {
    root: assetDirectory,
    path: relativeRequestPath,
    contentTypes: mimeTypes,
    headers: { "Content-Security-Policy": contentSecurityPolicy },
  });
}

function createWindow() {
  mainWindow = new BrowserWindow({
    title: "inkling",
    width: 1280,
    height: 720,
    // 320px matches the body min-width in src/index.css. At 240px high the library grid shrinks to 65px; 360px keeps it near 185px.
    minWidth: 320,
    minHeight: 360,
    frame: false,
    titleBarStyle: "hidden",
    titleBarOverlay: { color: "#00000000", symbolColor: "#e5ddd2", height: 32 },
    autoHideMenuBar: true,
    backgroundColor: "#0c0c0b",
    show: false,
    webPreferences: {
      preload: join(mainDirectory, "preload.cjs"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
      webSecurity: true,
      // HTML-in-Canvas, so liquid glass can refract the live grid. Chromium
      // ships it behind this flag; without it the renderer keeps the CSS glass.
      enableBlinkFeatures: "CanvasDrawElement",
    },
  });
  mainWindow.setMenu(null);
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    const externalUrl = parseHttpUrlCore(url)?.toString();
    if (externalUrl) void shell.openExternal(externalUrl).catch(() => {});
    return { action: "deny" };
  });
  mainWindow.webContents.on("will-navigate", (event, target) => {
    let url;
    try {
      url = new URL(target);
    } catch {
      event.preventDefault();
      return;
    }
    if (url.protocol !== "app:" || url.hostname !== "local") event.preventDefault();
  });
  // The renderer calls inkling:window:ready once it knows whether the welcome
  // runs and has painted that first frame, so a first launch never flashes the
  // library before onboarding. The timer only guards against a renderer that
  // never says so: the window must always appear.
  mainWindow.once("ready-to-show", () => {
    const window = mainWindow;
    setTimeout(() => {
      if (window && !window.isDestroyed() && !window.isVisible()) window.show();
    }, 3000);
  });
  mainWindow.on("closed", () => {
    mainWindow = undefined;
  });

  const query = isPreview ? "?preview=1" : "";
  void mainWindow.loadURL(`app://local/index.html${query}`);
}

const hasSingleInstanceLock = app.requestSingleInstanceLock();
if (!hasSingleInstanceLock) {
  app.quit();
} else {
  app.on("second-instance", (_event, argv) => {
    handleDeepLinkArguments(argv);
    if (mainWindow) {
      if (mainWindow.isMinimized()) mainWindow.restore();
      mainWindow.focus();
    }
  });
  app.on("open-url", (event, url) => {
    event.preventDefault();
    enqueueDeepLink(url);
  });

  void app.whenReady().then(async () => {
    if (app.isPackaged) app.setAsDefaultProtocolClient("inkling");
    else {
      app.setAsDefaultProtocolClient("inkling", process.execPath, [
        resolve(process.argv[1] ?? "."),
      ]);
    }
    registerLibraryCommands();
    try {
      captureServer = await startCaptureServer({
        libraryDirectory,
        captureUrl: (input) => {
          if (!libraryStorage) initializeLibraryStorage();
          return requireLibraryStorage().captureUrl(input);
        },
      });
    } catch (error) {
      console.error(
        `capture server unavailable: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
    await protocol.handle("app", serveAppAsset);
    allowCanvasReadableImages();
    handleDeepLinkArguments(process.argv);
    createWindow();

    app.on("activate", () => {
      if (BrowserWindow.getAllWindows().length === 0) createWindow();
    });
    app.on("window-all-closed", () => {
      if (process.platform !== "darwin") app.quit();
    });
    let quitDrainStarted = false;
    let quitDrainComplete = false;
    app.on("before-quit", (event) => {
      if (quitDrainComplete) return;
      event.preventDefault();
      if (quitDrainStarted) return;
      quitDrainStarted = true;
      jobWorker?.stop();
      thumbnailWorker?.stop();
      void (async () => {
        try {
          await captureServer?.close();
        } catch (error) {
          console.error(
            `capture server shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
          );
        }
        try {
          await aiJobProcessors?.close();
        } catch (error) {
          console.error(
            `background jobs shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
          );
        }
        try {
          libraryStorage?.db.close();
        } catch (error) {
          console.error(
            `library shutdown failed: ${error instanceof Error ? error.message : String(error)}`,
          );
        }
        quitDrainComplete = true;
        app.quit();
      })();
    });
  });
}

import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { createEmbeddingEngine } from "./embeddings.mjs";
import { IMAGE_MODEL } from "./embedding-contract.mjs";
import { createTesseractOcr } from "./ocr.mjs";
import {
  IMAGE_PALETTE_JOB,
  IMAGE_THUMBNAIL_JOB,
  markdownToPlainText,
  PDF_THUMBNAIL_JOB,
  VIDEO_POSTER_JOB,
} from "./storage.mjs";

async function itemAsset(storage, item) {
  if (!item?.localAssetPath) throw new Error("item has no local asset path");
  return readFile(await storage.resolveAssetPath(item.localAssetPath));
}

export function embeddingText(item) {
  const bodyValue = String(item.body ?? "").trim();
  const body = bodyValue
    ? item.bodyFormat === "md"
      ? markdownToPlainText(bodyValue)
      : bodyValue
    : null;
  const description = body ?? item.description;
  const parts = [item.title, description, item.ocrText]
    .map((value) => String(value ?? "").trim())
    .filter(Boolean);

  if (body == null) {
    for (const key of ["text", "extractedText"]) {
      const value = String(item.metadata?.[key] ?? "").trim();
      if (value) parts.push(value);
    }
  }

  return parts.length ? parts.join("\n\n") : null;
}

export function enqueueStaleImageEmbeddings(storage) {
  const items = storage.db
    .prepare(`SELECT e.item_id FROM item_embeddings e JOIN items i ON i.id = e.item_id
      WHERE e.kind = 'image' AND e.model != ? AND i.kind = 'image'`)
    .all(IMAGE_MODEL);
  for (const item of items)
    storage.jobs.enqueue(item.item_id, "generate_embedding", { notify: false });
  return items.length;
}

export function createAiJobProcessors({
  modelCacheDirectory,
  bundledModelDirectory,
  ocr = createTesseractOcr({ cacheDirectory: join(modelCacheDirectory, "tesseract") }),
  embeddings = createEmbeddingEngine(modelCacheDirectory, undefined, bundledModelDirectory),
  extractPdf,
  extractUrl = async (sourceUrl) => {
    const { ingestUrl } = await import("../dist/electron/url-ingestion.mjs");
    return ingestUrl(sourceUrl);
  },
  nativeImage,
} = {}) {
  let thumbnailCursor = 0;
  let thumbnailBackfillDone = false;
  let paletteCursor = 0;
  let paletteBackfillDone = false;
  let posterCursor = 0;
  let posterBackfillDone = false;

  const processors = {
    async enrich_url(job, storage, workerId) {
      const item = storage.getItem(job.itemId);
      if (!item) throw new Error("item not found");
      if (!item.sourceUrl) throw new Error("URL item has no source URL");
      const article = await extractUrl(item.sourceUrl);
      storage.applyUrlEnrichment(job.id, workerId, article);
    },

    async ocr_image(job, storage, workerId) {
      const item = storage.getItem(job.itemId);
      if (!item) throw new Error("item not found");
      storage.jobs.updateProgress(job.id, workerId, 0, 1, "Reading image");
      const text = (await ocr.recognize(await itemAsset(storage, item))).trim();
      if (text) {
        storage.storeOcrText(item.id, text, "tesseract.js");
        storage.jobs.enqueue(item.id, "generate_embedding");
        storage.jobs.updateProgress(job.id, workerId, 1, 1, "Image text indexed");
      } else {
        storage.jobs.updateProgress(job.id, workerId, 1, 1, "No text found");
      }
    },

    async ocr_pdf_page(job, storage, workerId) {
      const item = storage.getItem(job.itemId);
      if (!item) throw new Error("item not found");
      let result;
      try {
        const pdfBytes = await itemAsset(storage, item);
        const extract = extractPdf ?? (await import("./pdf.mjs")).extractPdfTextByPages;
        result = await extract(pdfBytes, {
          recognize: (image) => ocr.recognize(image),
          onFirstPageThumbnail: item.thumbnailPath
            ? undefined
            : (png) => storage.storePdfThumbnail(item.id, png),
          onProgress: (current, total, message) =>
            storage.jobs.updateProgress(job.id, workerId, current, total, message),
        });
      } finally {
        if (!storage.getItem(item.id)?.thumbnailPath) {
          thumbnailCursor = 0;
          thumbnailBackfillDone = false;
        }
      }
      const pageCount = result.pages.length;
      if (result.text) {
        storage.storeOcrText(item.id, result.text, result.engine);
        storage.jobs.enqueue(item.id, "generate_embedding");
        storage.jobs.updateProgress(job.id, workerId, pageCount, pageCount, "PDF text indexed");
      } else {
        storage.jobs.updateProgress(job.id, workerId, pageCount, pageCount, "No text found");
      }
    },

    async [PDF_THUMBNAIL_JOB](job, storage) {
      const item = storage.getItem(job.itemId);
      if (!item) throw new Error("item not found");
      const pdfBytes = await itemAsset(storage, item);
      const { renderPdfFirstPage } = await import("./pdf.mjs");
      await storage.storePdfThumbnail(item.id, await renderPdfFirstPage(pdfBytes));
    },

    async [IMAGE_PALETTE_JOB](job, storage) {
      const item = storage.getItem(job.itemId);
      if (item?.kind !== "image") throw new Error("image item not found");
      if (!item.thumbnailPath) throw new Error("image thumbnail is not ready");
      const { dominantImageColors } = await import("./thumbnail.mjs");
      const colors = await dominantImageColors(
        await readFile(await storage.resolveAssetPath(item.thumbnailPath)),
      );
      storage.storeImagePalette(item.id, colors);
    },

    async generate_embedding(job, storage, workerId) {
      const item = storage.getItem(job.itemId);
      if (!item) throw new Error("item not found");
      const text = embeddingText(item);
      const total = Number(Boolean(text)) + Number(item.kind === "image");
      storage.jobs.updateProgress(
        job.id,
        workerId,
        0,
        total,
        "Loading local Nomic embedding models",
      );
      let current = 0;

      if (text) {
        const embedding = await embeddings.embedText(text);
        storage.storeEmbedding(
          item.id,
          "text",
          embedding.model,
          embedding.bytes,
          embedding.vector.length,
        );
        current += 1;
        storage.jobs.updateProgress(job.id, workerId, current, total, "Text search index ready");
      }

      if (item.kind === "image") {
        const embedding = await embeddings.embedImage(await itemAsset(storage, item));
        storage.storeEmbedding(
          item.id,
          "image",
          embedding.model,
          embedding.bytes,
          embedding.vector.length,
        );
        storage.jobs.updateProgress(
          job.id,
          workerId,
          current + 1,
          total,
          "Image similarity index ready",
        );
      }
    },
  };

  // A separate set because it runs on its own worker: a new card waits on these
  // jobs, and OCR or model loading can hold the main worker for minutes.
  const thumbnailProcessors = {
    async [IMAGE_THUMBNAIL_JOB](job, storage) {
      const item = storage.getItem(job.itemId);
      if (item?.kind !== "image") throw new Error("image item not found");
      if (await storage.storeImageThumbnail(item.id, await itemAsset(storage, item))) {
        storage.jobs.enqueue(item.id, IMAGE_PALETTE_JOB, { notify: false });
      }
    },

    async [VIDEO_POSTER_JOB](job, storage) {
      const item = storage.getItem(job.itemId);
      if (item?.kind !== "video") throw new Error("video item not found");
      if (!item.localAssetPath) throw new Error("item has no local asset path");
      const { createVideoPoster } = await import("./video-poster.mjs");
      const poster = await createVideoPoster(await storage.resolveAssetPath(item.localAssetPath), {
        nativeImage,
      });
      if (!poster) throw new Error("no poster available for this video");
      await storage.storeVideoPoster(item.id, poster);
    },
  };

  return {
    processors,
    thumbnailProcessors,
    onIdle(storage) {
      if (!paletteBackfillDone) {
        const nextPalette = storage.nextImagePaletteCandidate(paletteCursor);
        if (nextPalette) {
          storage.jobs.enqueue(nextPalette.id, IMAGE_PALETTE_JOB, { notify: false });
          paletteCursor = nextPalette.rowid;
          return;
        }
        paletteBackfillDone = true;
      }
      if (!posterBackfillDone) {
        const nextPoster = storage.nextVideoPosterCandidate(posterCursor);
        if (nextPoster) {
          storage.jobs.enqueue(nextPoster.id, VIDEO_POSTER_JOB, { notify: false });
          posterCursor = nextPoster.rowid;
          return;
        }
        posterBackfillDone = true;
      }
      if (thumbnailBackfillDone) return;
      const next = storage.nextPdfThumbnailCandidate(thumbnailCursor);
      if (!next) {
        thumbnailBackfillDone = true;
        return;
      }
      storage.jobs.enqueue(next.id, PDF_THUMBNAIL_JOB, { notify: false });
      thumbnailCursor = next.rowid;
    },
    embedQuery: async (text) => (await embeddings.embedQuery(text)).vector,
    close: () => ocr.close?.(),
  };
}

