  // belongs to a process that is gone and can be handed back right away.
  const recoverAfterExclusiveStartup = requeue(sql.literal("1 = 1"));

  const recoverExpired = Effect.suspend(() => {
    const expiry = now();
    return requeue(sql`(lease_until IS NULL OR lease_until <= ${expiry})`);
  });

  return {
    notify,
    enqueued,
    enqueue,
    getForItems,
    getForItem,
    countActive,
    enqueueOcr,
    claimNext,
    renew,
    complete,
    fail,
    release,
    updateProgress,
    retry,
    recoverAfterExclusiveStartup,
    recoverExpired,
  };
});

