// The Promise face of a service, for IPC handlers and tests. Rejections carry
// the storage message the renderer shows, not the SQL client's summary.
export function promised<T extends object>(
  service: T,
  run: <A, E>(effect: Effect.Effect<A, E>) => Promise<A>,
): Promised<T> {
  const call = (method: (...args: unknown[]) => unknown) => (...args: unknown[]) => {
    const result = method(...args);
    if (!Effect.isEffect(result)) return result;
    return run(result).catch((error: unknown) => {
      throw toError(error);
    });
  };
  return Object.fromEntries(
    Object.entries(service).map(([key, value]) => [key, typeof value === "function" ? call(value) : value]),
  ) as Promised<T>;
}
