  await library.jobs.enqueue("next-item", "blocked");

  const started = Promise.withResolvers<void>();
  let processed = 0;
  const worker = await library.worker({
    processors: {
      blocked: () =>
        Effect.sync(() => {
          processed += 1;
          started.resolve();
        }).pipe(Effect.andThen(Effect.never)),
    },
  });
  const stop = worker.start();
  await started.promise;
  await stop();

  expect(processed).toBe(1);
  expect(
    library.db.prepare("SELECT item_id, status, retry_count, worker_id FROM jobs ORDER BY item_id").all(),
  ).toEqual([
    { item_id: "first-item", status: "pending", retry_count: 0, worker_id: null },
