    headers: {
      Authorization: `Bearer ${originalToken}`,
      Origin: "https://example.com",
    },
  });
  expect(deniedOrigin.status).toBe(403);
  const acceptedHealth = await fetch(status.healthUrl, {
    headers: {
      Authorization: `Bearer ${originalToken}`,
      Origin: "chrome-extension://abcdef",
