455	export function summariesFromJobs(itemIds: string[], jobs: ProcessingJob[]) {
456	  const grouped = new Map<string, ProcessingJob[]>();
457	  for (const job of jobs) {
458	    const group = grouped.get(job.itemId) ?? [];
459	    group.push(job);
460	    grouped.set(job.itemId, group);
461	  }
462	  return new Map(itemIds.map((id) => [id, summarizeProcessingJobs(grouped.get(id) ?? [])]));
463	}
